const SOURCES={cpi:'https://www.ssb.no/priser-og-prisindekser/konsumpriser/statistikk/konsumprisindeksen',forecast:'https://www.norges-bank.no/aktuelt/publikasjoner/Pengepolitisk-rapport/2026/ppr-32026/nettrapport-ppr-32026/',fund:'https://www.forbrukerradet.no/sparing-i-fond-og-spareprofiler/',age:'https://vff.no/documents/Faktablad/2026/Spareavtaleunders%C3%B8kelsen/FAKTAARK_Spareavtaleunders%C3%B8kelsen-10.07.26.pdf'};
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`;
const AGE={'all':{label:'Alle voksne',value:56,n:1000},'18-29':{label:'18 til 29 år',value:49,n:187},'30-39':{label:'30 til 39 år',value:76,n:176},'40-49':{label:'40 til 49 år',value:67,n:161},'50+':{label:'50 år og eldre',value:48,n:476}};
const CONTEXT_SOURCES={buffer:'https://www.ssb.no/sosiale-forhold-og-kriminalitet/levekar/statistikk/fattigdomsproblemer-levekarsundersokelsen',bank:'https://www.ssb.no/inntekt-og-forbruk/skatt-for-personer/statistikk/skatt-for-personer/artikler/god-vekst-i-personinntekt-lonn',survey:'https://vff.no/documents/Faktablad/2026/Befolkningsunders%C3%B8kelsen/Fondsunders%C3%B8kelsen-2026.pdf'};
const AGE_CHOICES={'all':'Alle voksne','18-24':'18 til 24 år','25-29':'25 til 29 år','30-34':'30 til 34 år','35-39':'35 til 39 år','40-44':'40 til 44 år','45-49':'45 til 49 år','50-54':'50 til 54 år','55-66':'55 til 66 år','67+':'67 år og eldre'};
const BUFFER_STATS=[{label:'16 til 24 år',max:24,value:19.9},{label:'25 til 44 år',max:44,value:26.1},{label:'45 til 66 år',max:66,value:21.1},{label:'67 år og eldre',max:Infinity,value:11.2}];
const BANK_STATS=[{label:'17 til 34 år',max:34,mean:170500,median:68300},{label:'35 til 54 år',max:54,mean:264100,median:81400},{label:'55 til 66 år',max:66,mean:535300,median:143400},{label:'67 år og eldre',max:Infinity,mean:834800,median:377700}];
function ageStatistics(key){
 const all=key==='all',age=Number.parseInt(key,10);
 return {buffer:all?{label:'Alle 16+',value:20.6}:BUFFER_STATS.find(x=>age<=x.max),bank:all?{label:'Alle 17+',mean:407500,median:112200}:BANK_STATS.find(x=>age<=x.max),fund:AGE[all?'all':age<30?'18-29':age<40?'30-39':age<50?'40-49':'50+']};
}
function ageText(){
 const legacy={'18-29':['18-24','25-29'],'30-39':['30-34','35-39'],'40-49':['40-44','45-49'],'50+':['50-54','55-66','67+']};
 const oldGroup=legacy[s.ageGroup];
 if(!Object.hasOwn(AGE_CHOICES,s.ageGroup))s.ageGroup='all';
 const {buffer,bank,fund}=ageStatistics(s.ageGroup),selected=AGE_CHOICES[s.ageGroup];
 const distribution=[['0 til 249 kr',6],['250 til 499 kr',9],['500 til 999 kr',13],['1 000 til 1 999 kr',25],['2 000 til 5 000 kr',29],['Over 5 000 kr',18]];
 const fmt=n=>new Intl.NumberFormat('nb-NO').format(n);
 return `<section class="age-result" aria-live="polite"><div class="eyebrow">ØKONOMI ETTER ALDER</div><h3>${selected}</h3><p>Statistikk fra SSB og Opinion. Velg aldersgruppe for å oppdatere kortene.</p><p class="hint">Hver kilde bruker sine egne aldersintervaller, som vises på kortene. Nabogrupper kan derfor få samme tall. Dette er gruppestatistikk, ikke et individuelt estimat eller en fasit for hva du bør ha spart.</p>${oldGroup?'<p>Vi har delt de gamle aldersgruppene i mindre intervaller. Velg aldersgruppen din på nytt.</p>':''}</section>
 <div class="context-cards">
 <article><div class="eyebrow">01 · BUFFER · SSB 2025</div><p class="stat-group">${buffer.label} · Utvalgsundersøkelse</p><h3>${fmt(buffer.value)} %</h3><p>kunne ikke dekke en uventet utgift på <b>22 000 kr</b>.</p><p>Hele befolkningen 16+: <b>20,6 %</b>.</p><p class="hint">Personer i husholdninger som ikke kunne betale innen én måned uten ekstra lån, salg av eiendeler eller hjelp. Dette måler økonomisk handlingsrom, ikke hvor mye den enkelte har på bufferkonto. ${link('https://www.ssb.no/statbank/table/12123','SSB tabell 12123')}.</p></article>
 <article><div class="eyebrow">02 · BANKINNSKUDD · SSB 2025</div><p class="stat-group">${bank.label} · Foreløpig registerstatistikk</p><h3>${fmt(bank.median)} kr</h3><p>Median. Halvparten med bankinnskudd hadde mindre, halvparten mer.</p><p><b>${fmt(bank.mean)} kr</b> i gjennomsnitt.</p><p class="hint">Bosatte personer 17+ med bankinnskudd, begge kjønn. Alle bankkontoer, ikke bare buffer. Hverken fond, bolig eller gjeld inngår. Hele landet: median 112 200 kr, gjennomsnitt 407 500 kr. ${link('https://www.ssb.no/statbank/table/14782','SSB tabell 14782')}.</p></article>
 <article><div class="eyebrow">03 · AKSJEFOND · OPINION 2026</div><p class="stat-group">${fund.label} · Utvalgsundersøkelse</p><h3>${fund.value} %</h3><p>oppga aksjefond, <b>inkludert pensjon gjennom arbeidsgiver</b>.</p><p>Alle voksne: <b>56 %</b> med samme definisjon.</p><p class="hint">${fund.n} svarpersoner i gruppen. Opinion for VFF, mai 2026, vektet webpanel. Mindre undergrupper har større statistisk usikkerhet. Måler utbredelse, ikke sparebeløp. ${link(CONTEXT_SOURCES.survey+'#page=8','Kilde og aldersfordeling')}.</p></article></div>
 <h3 class="national-heading">Månedssparing: nasjonalt sammenligningsgrunnlag</h3><p class="hint">Ingen verifisert aldersfordeling for samlet månedssparing i datagrunnlaget her. Fordelingen under gjelder alle aldre og endres derfor ikke med aldersvalget.</p>
 <div class="context-monthly"><h3>Hvor mye setter fondsparere av hver måned?</h3><p>Samlet beløp i alle spareavtaler blant de <b>360 respondentene</b> som besvarte beløpsspørsmålet i fondsundersøkelsen. Ikke hele befolkningen.</p><div class="distribution">${distribution.map(([label,value])=>`<div class="dist-row"><span>${label}</span><div class="dist-track"><i style="width:${value}%"></i></div><b>${value} %</b></div>`).join('')}</div><p class="hint">Selvrapporterte beløp, mai 2026. Gruppene gir ikke et presist gjennomsnitt eller en eksakt median i kroner. Bankinnskudd og annen sparing er ikke kartlagt som samlet personlig sparing her. ${link(CONTEXT_SOURCES.survey+'#page=14','Opinion for VFF, side 14')}.</p></div>

 <details class="context-detail"><summary>Statistikk, estimat og hva tallene betyr</summary><p>Bankinnskudd er foreløpige registertall. Buffer og fond er undersøkelsesbaserte anslag for befolkningsgrupper. Ingen av kortene beregner et personlig sparebeløp ut fra alder.</p><p>Kildenes opprinnelige aldersintervaller er beholdt. Vi fordeler ikke et bredt gruppetall kunstig på enkeltaldre. Median beskriver midtpunktet; gjennomsnitt påvirkes av store beløp. Bankinnskudd er en beholdning, mens månedssparing er nye penger som settes av.</p><p>Inntekt, gjeld, husholdning og livssituasjon varierer mye innenfor samme aldersgruppe. Bruk oversikten som bakgrunn for din egen plan.</p></details><p class="hint">Kildegrunnlag kontrollert 20. oktober 2026. Daterte tall, ingen automatisk oppdatering. Startbeløpet i spareplanen kan inneholde fond og sammenlignes derfor ikke direkte med bankstatistikken.</p>`;
}
const historical=(Math.pow(100/72.6,1/10)-1)*100;
const HELP={
inflation:['Inflasjon: hva bør jeg bruke?',`<p>Inflasjon svekker kjøpekraften. Det finnes ikke ett sikkert tall for hele spareperioden.</p><table><tr><th>Grunnlag</th><th>Prisvekst</th></tr><tr><td>2015 til 2025, årlig geometrisk vekst¹</td><td>ca. ${dec.format(historical)} %</td></tr><tr><td>2025, årsgjennomsnitt</td><td>3,0 %</td></tr><tr><td>September 2026, siste 12 måneder</td><td>3,4 %</td></tr><tr><td>Norges Banks langsiktige mål</td><td>2,0 %</td></tr></table><p class="hint">¹ Beregnet fra SSBs avrundede årsindekser: 72,6 i 2015 og 100 i 2025, med 2025 som basisår. Revidert serie. Historie er ikke en prognose. ${link(SOURCES.cpi,'SSBs KPI-serie')}.</p><h3>Forventet utvikling</h3><p>Norges Banks PPR 3/2026 anslår årlig KPI-vekst til 3,3 % i 2026, 2,6 % i 2027, 2,3 % i 2028 og 2,1 % i 2029. Dette er en usikker prognose for bestemte kalenderår. ${link(SOURCES.forecast,'Se prognosen, tabell 3')}.</p><h3>Hva er mest sannsynlig?</h3><p>Prognosen er et faglig hovedscenario for de nærmeste årene, ikke et sikkert tall for 30 år. Her kan 2,5 % brukes som en egen langsiktig regneforutsetning. Test også 2 % og 4 %. 2 % er et mål; 2,5 % og 4 % er våre testverdier, ikke offisielle langtidsprognoser.</p><div class="help-presets"><button data-inflation="2">Prøv 2 %</button><button data-inflation="2.5">Prøv 2,5 %</button><button data-inflation="4">Prøv 4 %</button></div>`],
rate:['Avkastning og usikkerhet',`<p>Effektiv årlig avkastning før kostnader og skatt. Historisk avkastning varierer med marked, valuta og periode og gir ingen garanti.</p><p>Dette er antatt årlig vekst gjennom perioden. Du kan også skrive inn negativ vekst. I virkeligheten varierer avkastningen fra år til år, og verdien kan falle mye. Det kan du teste med «Børsfall» eller ved å vise lavere og høyere vekst.</p><p>Kalkulatoren har ikke et dokumentert «mest sannsynlig» markedsutfall. Midtlinjen følger tallet du velger. Lavere og høyere vekst er følsomhetstester. Med indeksfond valgt viser grafen lavere og høyere scenario fra en forenklet modell, ikke en garanti.</p><p>En høy aksjeandel kan gi høyere forventet langsiktig avkastning og større tap underveis. Bred spredning og lave kostnader kan være nyttig ved langsiktig sparing. ${link(SOURCES.fund,'Forbrukerrådets veiledning')}.</p>`],
monthly:['Økonomien i perspektiv',`<div id="helpAge"></div><button id="goAge">Åpne statistikken etter alder</button>`],
start:['Startbeløp','<p>Pengene du allerede har satt av til denne planen. Unngå å telle den samme bufferen eller de samme pengene i flere mål.</p>'],
years:['Spareperiode','<p>Antall år frem til pengene skal brukes. Avrundes til nærmeste måned. En kort, fast frist gir mindre rom for å vente ut børsfall.</p>'],
goal:['Sparemål og kjøpekraft','<p>Velg om målet er et fremtidig kronebeløp eller dagens kjøpekraft. Med «dagens kroner» øker det nominelle målet med inflasjonen du har valgt.</p>'],
fee:['Årlige kostnader',`<p>Ta med både fondskostnad og eventuelt plattformgebyr, uten å telle samme kostnad to ganger. Kalkulatoren trekker kostnaden fra kapitalen og inkluderer tapt rentes rente. ${link(SOURCES.fund,'Om fondskostnader')}.</p>`],
growth:['Årlig endring i månedssparingen','<p>Hvor mye sparebeløpet endres per år. Et positivt tall betyr at du øker sparingen, et negativt tall at du reduserer den. Endringen fordeles jevnt over månedene. 0 % betyr samme kronebeløp hele perioden.</p>'],
bank:['Bankrente','<p>En antatt rente for hele perioden, før skatt. Flytende rente kan endre seg. Bruk bankens effektive rente og sjekk uttaksregler, binding og innskuddsgaranti.</p>'],
spread:['Alternative scenarioer','<p>Avvik i prosentpoeng fra valgt avkastning. 6 % med avvik 2 gir 4 % og 8 %. Dette er ikke et statistisk sannsynlighetsintervall.</p>'],
extra:['Ekstrainnskudd','<p>Et engangsbeløp i tillegg til månedssparingen. Oppgis i kroner på innskuddstidspunktet.</p>'],
extraYear:['Når kommer innskuddet?','<p>År etter at sparingen starter. År 0 betyr med en gang.</p>'],
crash:['Stresstest: børsfall','<p>Et enkelt fall i kapitalen på valgt tidspunkt. Deretter fortsetter valgt avkastning. Fallet hentes ikke automatisk inn igjen, og eksemplet er ikke en prognose.</p>'],
crashYear:['Når skjer fallet?','<p>År etter starten av sparingen. Flytt fallet nær kjøpsdatoen for å undersøke risikoen ved en fast frist.</p>'],
annualWithdraw:['Årlig uttak','<p>Første årsbeløp i kroner ved uttaksstart. Uttaket skjer ved slutten av året. Inflasjonsjustering øker beløpet fra år 2.</p>'],
retireYears:['Uttaksperiode','<p>Antall hele uttaksår. I «hvor mye kan jeg ta ut» fordeles kapitalen over perioden. I de andre valgene bestemmer feltet hvor mange år tabellen viser.</p>'],
withdrawPercent:['Prosentuttak','<p>Velg mellom prosent av gjenværende saldo etter årets avkastning og prosent av startkapitalen. Det første gir varierende kronebeløp. Det andre gir et første årsbeløp som eventuelt inflasjonsjusteres.</p>'],
extraWithdraw:['Ekstrauttak','<p>Et engangsuttak etter vanlig uttak i valgt år. Tas med i saldo og varighet. Inflasjonsjusteringen for ekstrauttaket er et eget valg.</p>'],
extraWithdrawYear:['År for ekstrauttak','<p>Helt år etter at spareperioden er ferdig. År 5 betyr fem år inn i uttaksperioden.</p>'],
dreamCost:['Pris og budsjett','<p>Beløpet du vil finansiere med sparing. For bolig kan dette være egenkapital og kjøpskostnader, ikke hele boligprisen. Budsjettet her er ikke en vurdering av låneevne.</p>'],
dreamStart:['Allerede satt av','<p>Pengene som er øremerket akkurat dette kjøpet. Unngå å bruke samme startbeløp i flere parallelle mål.</p>'],
dreamYears:['Tid til kjøpet','<p>Tiden frem til kjøpsdatoen, avrundet til nærmeste måned. Har du fast frist og kort horisont, bør du ikke være avhengig av oppgang i aksjemarkedet.</p>'],
dreamMonthly:['Ditt månedsbudsjett','<p>Hvor mye du kan sette av hver måned. Alternativene viser både hva dette kan gi og hva du må spare for å nå målet med hver forutsetning.</p>'],
dreamInflation:['Prisvekst for dette kjøpet','<p>Prisene på bolig, biler og ferier kan utvikle seg annerledes enn generell inflasjon. Dette er din egen prisforutsetning, ikke en særskilt prisprognose. Den brukes bare hvis budsjettet er i dagens priser.</p>'],
dreamSafe:['Bank: regneforutsetning','<p>Antatt effektiv bankrente etter eventuelle kostnader, før skatt. Dette er ikke et tilbud eller en rentegaranti for hele perioden. Vi tester også 0 % rente.</p>'],
dreamModerate:['Moderat risiko: regneforutsetning','<p>Illustrasjon for en blanding av bank/renter og aksjefond. Tallet er etter kostnader, før skatt. En slik blanding kan tape verdi. Vi illustrerer et fall på 15 % rett før kjøpet, uten å hevde at dette er største mulige tap.</p>'],
dreamRisk:['Høyere risiko: regneforutsetning','<p>Illustrasjon for en høy aksjeandel med bred spredning. Tallet er etter kostnader, før skatt. Vi tester et fall på 35 % rett før kjøpet. Faktiske fall kan være større. Høyere forventet avkastning betyr ikke sikrere måloppnåelse.</p>']
};
for(const [group,fields] of Object.entries({dreamFields:[['dreamCost','Budsjett for kjøpet','kr'],['dreamStart','Allerede satt av','kr'],['dreamYears','Tid til kjøpet','år'],['dreamMonthly','Jeg kan spare per måned','kr'],['dreamInflation','Årlig prisvekst for kjøpet','%']],dreamRates:[['dreamSafe','Bank / lavere risiko','%'],['dreamModerate','Moderat risiko','%'],['dreamRisk','Høyere risiko','%']]}))$(group).innerHTML=fields.map(([id,label,unit])=>`<div class="field"><label for="${id}" class="field-label">${label}</label><span class="fieldbox"><input id="${id}" type="text" inputmode="decimal"><span class="unit">${unit}</span></span></div>`).join('');
function setPage(page){
 s.activePage=['calculator','dreams','withdrawals'].includes(page)?page:'calculator';document.body.dataset.page=s.activePage;
 const intro={calculator:['Hva kan sparingen <em>bli?</em>','Start med fire tall. Se resultatet, og utforsk det som betyr noe for deg.'],dreams:['Hvor mye må du <em>spare?</em>','Velg et mål og en dato. Se hva du må sette av, og sammenlign alternativene.'],withdrawals:['Hvor lenge varer <em>pengene?</em>','Planlegg faste uttak, eller finn et årsbeløp som passer perioden.']}[s.activePage];$('pageTitle').innerHTML=intro[0];$('introText').textContent=intro[1];
 for(const [id,p]of [['calculatorPanel','calculator'],['dreamPanel','dreams'],['withdrawalPanel','withdrawals']])$(id).hidden=s.activePage!==p;
 for(const [id,p]of [['calculatorPage','calculator'],['dreamPage','dreams'],['withdrawalPage','withdrawals']])$(id).setAttribute('aria-pressed',s.activePage===p);
 if(s.activePage==='calculator'&&rows.length)chart();
}
$('calculatorPage').onclick=()=>setPage('calculator');
$('dreamPage').onclick=()=>{setPage('dreams');renderDream();};
$('withdrawalPage').onclick=()=>{setPage('withdrawals');render();};
$('editCapital').onclick=()=>{setPage('calculator');$('start').focus();};
$('brandHome').onclick=e=>{e.preventDefault();setPage('calculator');window.scrollTo({top:0,behavior:'smooth'});};

function openHelp(key){const [title,body]=HELP[key];$('helpTitle').textContent=title;$('helpBody').innerHTML=body;if($('helpAge'))$('helpAge').innerHTML=ageText();if($('goAge'))$('goAge').onclick=()=>{$('helpDialog').close();$('ageGroup').closest('details').open=true;$('ageGroup').focus()};for(const b of $('helpBody').querySelectorAll('[data-inflation]'))b.onclick=()=>{s.inflation=Number(b.dataset.inflation);fill();render();$('helpDialog').close();notice('Inflasjonsforutsetningen i sparekalkulatoren er endret')};$('helpDialog').showModal()}
$('helpClose').onclick=()=>$('helpDialog').close();
for(const key of Object.keys(HELP)){const input=$(key);if(!input)continue;const label=input.closest('.field,label');if(!label)continue;const b=document.createElement('button');b.className='help-button';b.type='button';b.textContent='?';b.setAttribute('aria-label','Forklaring: '+HELP[key][0]);b.onclick=e=>{e.preventDefault();openHelp(key)};label.insertBefore(b,label.querySelector('.fieldbox'))}
function renderDream(){setPage(s.activePage);$('ageInfo').innerHTML=ageText();$('ageGroup').value=s.ageGroup;const hints={car:'Ta gjerne med omregistrering og utstyr i budsjettet. Løpende bilkostnader må få plass i økonomien etter kjøpet.',home:'Legg inn beløpet du skal spare selv, for eksempel egenkapital og kjøpskostnader. Lån, boligprisvekst, lånekrav og BSU er ikke beregnet her.',holiday:'En ferie med fast dato bør ikke være avhengig av et godt børsår.',renovation:'Legg gjerne til en reserve for uforutsette kostnader i budsjettet.',buffer:'En buffer må kunne brukes når noe uventet skjer. Vurder tilgjengelighet og bankvilkår, ikke bare rente.',freedom:'Ta med levekostnader og en buffer for perioden med mindre inntekt.',other:'Avklar om tidspunktet og budsjettet er fleksibelt før du velger risiko.'};$('dreamTypeTip').textContent=hints[s.dreamType]||hints.other;
 try{const plans=E.dreamPlans(s,fieldLabel);$('dreamPanel').classList.remove('stale');hidePending(Object.keys(E.DREAM_FIELDS));$('dreamError').hidden=true;$('dreamError').textContent='';syncFieldErrors(Object.keys(E.DREAM_FIELDS),'dreamError',null);$('dreamSummary').innerHTML=`<div><div class="eyebrow">MÅLET DITT VED KJØP</div><h2>${money(plans[0].goal)}</h2><p>Om ${dec.format(plans[0].plan.years)} år · ${s.dreamReal?'justert for valgt prisvekst':'fast nominelt budsjett'} · alle resultater før skatt</p></div>`;$('dreamCards').innerHTML='';const names={safe:['01','Lavere risiko','Bank med innskuddsgaranti'],moderate:['02','Moderat risiko','Blanding av bank/renter og aksjefond'],risk:['03','Høyere risiko','Høy aksjeandel, bredt fordelt']};for(const r of plans){const [num,title,sub]=names[r.id],short=r.plan.years<5,discourage=r.id!=='safe'&&(short||!s.dreamFlexible||s.dreamType==='buffer'||(s.riskChosen&&s.stress==='low')),gap=Math.max(0,r.goal-r.end);const d=document.createElement('article');d.className='route-card '+r.id;const recommendation=r.id==='safe'?'Et naturlig utgangspunkt når datoen er fast. Kontroller rentevilkår og hvilken garanti banken omfattes av. Norske medlemsbanker har normalt dekning inntil 2 mill. kr per kunde per bank.':discourage?'For dette målet bør pengene du må ha klare til fristen normalt stå med lavere risiko. Mer risiko kan gi et større underskudd når du skal kjøpe.':r.id==='moderate'?'Kan vurderes når du tåler tap og kan utsette kjøpet. Vurder lavere aksjeandel når kjøpsdatoen nærmer seg.':'Kan vurderes ved lang horisont og reell evne til å utsette kjøpet. En lang periode garanterer ikke gevinst.';
 d.innerHTML=`<div class="eyebrow">${dec.format(r.rate)} % ÅRLIG ETTER KOSTNADER</div><h3>${title}</h3><p class="route-sub">${sub}</p><strong class="route-money">${money(Math.ceil(r.required))}<small> per måned for å nå målet</small></strong><p>Med ditt budsjett: <b>${money(r.end)}</b><br>${gap>0?'Mangler '+money(gap):'Beregnet mål nådd'}</p><details class="route-stress"><summary>Hva hvis utviklingen blir svakere?</summary><b>${r.fall?'Hvis saldoen faller '+r.fall+' % før kjøpet':'Hvis bankrenten blir 0 % hele perioden'}</b><p>Med ditt månedsbeløp: ${money(r.stressed)}.<br>For å nå målet også i denne testen: ${money(Math.ceil(r.robust))}/mnd.</p></details><p class="route-advice">${recommendation}</p>`;
 const b=document.createElement('button');b.textContent='Bruk dette i spareplanen';b.onclick=()=>{undoState={state:{...s},mode,view:{...view}};$('undoBar').hidden=false;$('undoText').textContent='Målplanen er overført til sparekalkulatoren.';s={...s,start:r.plan.start,monthly:Math.ceil(r.required),years:r.plan.years,rate:r.rate,fee:0,growth:0,goal:r.plan.goal,goalReal:r.plan.goalReal,inflation:r.plan.inflation,extra:0,crash:0,spread:0,purpose:s.dreamType==='buffer'?'buffer':s.dreamType==='home'?'home':s.dreamType==='freedom'?'freedom':'dream',activePage:'calculator'};fill();render();setPage('calculator');notice('Målplanen er overført. Avkastning er etter kostnader, så kostnad er satt til 0.')};d.append(b);$('dreamCards').append(d)}
 }catch(e){if(e.field&&e.field===pendingKey()){$('dreamError').hidden=true;$('dreamError').textContent='';$('dreamPanel').classList.add('stale');showPending(e.field);return;}hidePending(Object.keys(E.DREAM_FIELDS));$('dreamPanel').classList.remove('stale');$('dreamError').hidden=false;$('dreamError').textContent=e.message;$('dreamCards').innerHTML='';$('dreamSummary').innerHTML='';syncFieldErrors(Object.keys(E.DREAM_FIELDS),'dreamError',e.field);}}
window.renderDream=renderDream;
